document.querySelector('#sponsor-brief')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const text='SPONSORSHIP INQUIRY BRIEF\n\nOrganization: '+data.get('organization')+'\nWebsite: '+data.get('website')+'\nPlacement: '+data.get('placement')+'\n\nProposal:\n'+data.get('idea')+'\n\nPrepared for '+document.title+'\nThis draft has not been submitted and does not reserve a placement.';const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='sponsorship-inquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#brief-status').textContent='Inquiry brief downloaded. No message has been submitted.';});
